package com.vietanh.bilingualquiz.ui;
import android.app.Activity; import android.content.Intent; import android.os.Bundle; import android.graphics.Color; import android.view.Gravity; import android.widget.*;
public class GradeSelectionActivity extends Activity { @Override public void onCreate(Bundle b){super.onCreate(b); boolean vi=getSharedPreferences("settings",MODE_PRIVATE).getBoolean("vietnamese",true); int first=getIntent().getIntExtra("firstGrade",1),last=getIntent().getIntExtra("lastGrade",5); LinearLayout screen=new LinearLayout(this); screen.setOrientation(LinearLayout.VERTICAL); screen.setGravity(Gravity.CENTER_HORIZONTAL); screen.setPadding(40,48,40,40); TextView title=new TextView(this); title.setText(vi?"Chọn lớp":"Choose grade"); title.setTextSize(24); title.setTextColor(Color.rgb(20,60,120)); screen.addView(title); for(int grade=first;grade<=last;grade++){final int g=grade; Button button=new Button(this); button.setText(vi?"Lớp "+grade:"Grade "+grade); button.setOnClickListener(v->{Intent i=new Intent(this,QuizActivity.class);i.putExtra("grade",g);startActivity(i);});screen.addView(button);}setContentView(screen);}}
